using System.Security.Cryptography;using System.Text;using System.Text.Json;using Microsoft.AspNetCore.WebUtilities;using Common.Security.Authenticators;using Common.Security.Models;using Common.Security.Options;
namespace Aegis.Diagnostics;
internal sealed record SuiteIdentity(string UserName,string DisplayName,string Title,string[] Permissions);internal sealed record SuiteTicket(string Sub,string Name,string Title,string[] Permissions,string Audience,long Expires,string Nonce);
internal sealed class SuiteSecurity(IConfiguration c,IHostEnvironment environment){const string Cookie="Aegis.Diagnostics.Session";const string DevelopmentSigningKey="Aegis-Suite-Development-Handoff-Key-v1-Operations-Configuration-Diagnostics";readonly byte[] key=Encoding.UTF8.GetBytes(GetSigningKey(c,environment));static string GetSigningKey(IConfiguration c,IHostEnvironment environment){string? configured=c["SuiteSecurity:SigningKey"];if(!string.IsNullOrWhiteSpace(configured))return configured;if(environment.IsDevelopment())return DevelopmentSigningKey;throw new InvalidOperationException("SuiteSecurity:SigningKey is required outside Development. Supply it through protected deployment configuration/OpenBao.");}public string Mode=>c["SuiteSecurity:Mode"]??"Mock";public SuiteIdentity? Authenticate(string u,string p){AuthenticationResult? r=null;if(Mode.Equals("ActiveDirectory",StringComparison.OrdinalIgnoreCase)){var o=new ActiveDirectoryAuthenticationOptions{Domain=c["SuiteSecurity:ActiveDirectory:Domain"]??"",SearchBase=c["SuiteSecurity:ActiveDirectory:SearchBase"]??"",Servers=c.GetSection("SuiteSecurity:ActiveDirectory:Servers").Get<string[]>()??[]};r=new ActiveDirectory(o).Authenticate(u,p);}else if(Mode.Equals("Mock",StringComparison.OrdinalIgnoreCase)&&c.GetValue("SuiteSecurity:Mock:Enabled",false)){var o=new MockAuthenticationOptions{Password=c["SuiteSecurity:Mock:Password"]??"",AllowAnyUser=c.GetValue("SuiteSecurity:Mock:AllowAnyUser",true),AllowedUsers=c["SuiteSecurity:Mock:AllowedUsers"],AdminUsers=c["SuiteSecurity:Mock:AdminUsers"]};r=new MockAuthenticator(o).Authenticate(u,p);}if(r?.IsAuthenticated!=true)return null;string[] perms=r.IsAdministrative?["Diagnostics.View","Diagnostics.Run","Diagnostics.Repair","Diagnostics.Critical","Security.Manage"]:["Diagnostics.View"];return new(u,r.UserInfo?.DisplayName??u,r.UserInfo?.Title??"User",perms);}public SuiteIdentity? Read(HttpRequest r)=>r.Cookies.TryGetValue(Cookie,out var v)?Validate(v):null;public SuiteIdentity? AcceptHandoff(string token)=>Validate(token);SuiteIdentity? Validate(string token){try{var p=token.Split('.');if(p.Length!=2)return null;byte[] d=WebEncoders.Base64UrlDecode(p[0]),sig=WebEncoders.Base64UrlDecode(p[1]);using var h=new HMACSHA256(key);if(!CryptographicOperations.FixedTimeEquals(h.ComputeHash(d),sig))return null;var t=JsonSerializer.Deserialize<SuiteTicket>(d);if(t is null||t.Audience!="Aegis.Diagnostics"||t.Expires<DateTimeOffset.UtcNow.ToUnixTimeSeconds())return null;return new(t.Sub,t.Name,t.Title,t.Permissions);}catch{return null;}}string Session(SuiteIdentity i){var t=new SuiteTicket(i.UserName,i.DisplayName,i.Title,i.Permissions,"Aegis.Diagnostics",DateTimeOffset.UtcNow.AddHours(8).ToUnixTimeSeconds(),Guid.NewGuid().ToString("N"));byte[] d=JsonSerializer.SerializeToUtf8Bytes(t);using var h=new HMACSHA256(key);return WebEncoders.Base64UrlEncode(d)+"."+WebEncoders.Base64UrlEncode(h.ComputeHash(d));}public void Set(HttpResponse r,SuiteIdentity i)=>r.Cookies.Append(Cookie,Session(i),new CookieOptions{HttpOnly=true,Secure=!environment.IsDevelopment(),SameSite=SameSiteMode.Lax,MaxAge=TimeSpan.FromHours(8)});}
internal static class SuiteSecurityExtensions{public static IServiceCollection AddSuiteSecurity(this IServiceCollection s)=>s.AddSingleton<SuiteSecurity>();public static void UseSuiteSecurity(this WebApplication app){app.Use(async(ctx,next)=>{if(ctx.Request.Path.StartsWithSegments("/health")||ctx.Request.Path.StartsWithSegments("/login")||ctx.Request.Path.StartsWithSegments("/auth")){await next();return;}var s=ctx.RequestServices.GetRequiredService<SuiteSecurity>();if(s.Read(ctx.Request) is null){ctx.Response.Redirect("/login?returnUrl="+Uri.EscapeDataString(ctx.Request.Path+ctx.Request.QueryString));return;}await next();});}public static void MapSuiteSecurity(this WebApplication app){app.MapGet("/login",(SuiteSecurity s,string? returnUrl)=>Results.Content(SuiteLoginPage.Render("Diagnostics",s.Mode,returnUrl),"text/html"));app.MapPost("/auth/login",async(HttpContext x,SuiteSecurity s)=>{var f=await x.Request.ReadFormAsync();var i=s.Authenticate(f["username"].ToString(),f["password"].ToString());if(i is null)return Results.Redirect("/login?error=1");s.Set(x.Response,i);return Results.Redirect(f["returnUrl"].ToString() is {Length:>0} r?r:"/");});app.MapGet("/auth/handoff",(string token,HttpContext x,SuiteSecurity s)=>{var i=s.AcceptHandoff(token);if(i is null)return Results.Redirect("/login?error=handoff");s.Set(x.Response,i);return Results.Redirect("/");});}}
